UPDATE STUDYMEMBER SET
	STUDY_ROLL = #{studyRoll}
WHERE MEM_ID = (SELECT MEM_ID FROM MEMBER WHERE MEM_LOGIN_ID = #{memLoginId}) AND STUDY_ID = #{studyId}

UPDATE STUDY
   SET STUDY_TITLE = #{studyTitle},
   	   STUDY_CATEGORY = #{studyCategory},
   	   STUDY_INTRO = #{studyIntro},
   	   STUDY_INTROCONTENT = #{studyIntrocontent}
 WHERE STUDY_ID = #{studyId}

